import test from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { layoutFor } from '../src/geometry.js'

// Golden cases generated by internal/geometry (Go). Any drift between
// preview and renderer geometry fails here.
const cases = JSON.parse(
  readFileSync(new URL('./geometry_cases.json', import.meta.url), 'utf8'),
)

const close = (a, b) => Math.abs(a - b) < 1e-9
const rectEq = (a, b) =>
  close(a.x, b.x) && close(a.y, b.y) && close(a.w, b.w) && close(a.h, b.h)

for (const c of cases) {
  test(`parity: ${c.name}`, () => {
    if (c.err) {
      assert.throws(
        () => layoutFor(c.sw, c.sh, c.cw, c.ch, c.mode, c.cropX, c.cropY),
        undefined, undefined,
        `expected error like Go: ${c.err}`,
      )
      return
    }
    const l = layoutFor(c.sw, c.sh, c.cw, c.ch, c.mode, c.cropX, c.cropY)
    assert.ok(rectEq(l.fg, c.layout.fg), `fg ${JSON.stringify(l.fg)} != ${JSON.stringify(c.layout.fg)}`)
    assert.ok(rectEq(l.srcVisible, c.layout.srcVisible), 'srcVisible mismatch')
    assert.ok(close(l.scale, c.layout.scale), 'scale mismatch')
    assert.equal(l.complete, c.layout.complete, 'complete mismatch')
    assert.equal(l.hasBackground, c.layout.hasBackground, 'hasBackground mismatch')
  })
}
